    out.push(...tagKey(raceBase(boxFaces3(0, -1.35, TW0, 1.0, (Z(7.05) - Z(6.58)) / 2, Z(6.58)), "terran"), key9(0, -1.35, Z(6.75))));   // 높이 반(요청)
