const BAKE_ONE_MAX = DEV9.bakeOneMB * 1024 * 1024;
const BAKE_POOL_BYTES = DEV9.bakePoolMB * 1024 * 1024;
/** 그 크기의 굽는 판을 빌린다 — 빌림터에 있으면 지워서 주고, 없으면 새로 짓는다. */
