        const ptAt = (t9: number): [number, number] => [
          ex + rx * Math.cos(t9) * cph - ry * Math.sin(t9) * sph,
          ey + rx * Math.cos(t9) * sph + ry * Math.sin(t9) * cph,
        ];
        const tx0 = Math.atan2(-ry * sph, rx * cph);
        const ty0 = Math.atan2(ry * cph, rx * sph);
        for (const t9 of [tx0, tx0 + Math.PI, ty0, ty0 + Math.PI]) {
          const off = sf === 1 ? norm9(t9 - a1) : norm9(a1 - t9);
          if (off <= span + 1e-9) { const [X9, Y9] = ptAt(t9); put(X9, Y9); }
        }
