      const bb = boxes.get(pid);
      if (!bb) { boxes.set(pid, [b[0], b[1], b[2], b[3]]); continue; }
      if (b[0] < bb[0]) bb[0] = b[0];
      if (b[1] < bb[1]) bb[1] = b[1];
      if (b[2] > bb[2]) bb[2] = b[2];
