      const w9 = cv.clientWidth;
      const h9 = cv.clientHeight;
      if (!w9 || !h9) return;                       // 관찰자가 상자가 서면 다시 부른다.
      const dpr9 = Math.min(3, window.devicePixelRatio || 1);
