      const key9 = spin === undefined ? "" : `${kind}|${spin}|${flat ? 1 : 0}|${pitchView ? 1 : 0}`
        + `|${viewYaw ?? 0}|${rotDeg}|${fit ? 1 : 0}|${cw9}x${ch9}|${cur9}`;
      const hit9 = key9 ? FX_RASTER_CACHE.get(key9) : undefined;
