  const [simTracks, setSimTracks] = useState<Map<number, TruthTrack> | null>(null);
  /* 참값 원본 — 자원·실시간 APM은 v2 꼴에 자리가 없어 여기서 직접 읽는다. */
  const [truth, setTruth] = useState<TruthTracks | null>(null);
